-- LÖVE 11 sample: `love examples/engines/love`
-- hero.lua and hero.png are generated by `npx tsx examples/build-samples.ts` (engine.love).
local sheet = require("hero")
local anim
local tags = { "idle_e", "walk_e", "idle_w", "walk_w" }

function love.load()
  love.graphics.setDefaultFilter("nearest", "nearest")
  love.window.setMode(960, 540)
  anim = sheet.new(love.graphics.newImage(sheet.image))
end

function love.update(dt)
  anim:update(dt)
end

function love.draw()
  love.graphics.clear(0.1, 0.11, 0.17)
  love.graphics.scale(3, 3)
  for i, tag in ipairs(tags) do
    anim:draw(tag, 40 + (i - 1) * 80, 100)
    love.graphics.print(tag, 22 + (i - 1) * 80, 120, 0, 0.5, 0.5)
  end
end
